mapper.select:
SELECT * FROM saved_results
WHERE share_id = #{shareId}
AND (expires_at IS NULL OR expires_at > UTC_TIMESTAMP())

mapper.update:
UPDATE saved_results
SET result_json = #{resultJson},
    net_annual_savings = #{netAnnualSavings},
    annual_reward = #{annualReward},
    total_annual_fees = #{totalAnnualFees}
WHERE user_id = #{userId}

UPDATE saved_results
SET share_id = #{shareId}, expires_at = DATE_ADD(NOW(), INTERVAL 30 DAY)
WHERE id = #{id}
